<script lang="ts">
 type Dist={MeanLeft:number;MedianLeft:number;StdDev:number}; type Bucket={LowerW:number;UpperW:number;Samples:number;DurationSeconds:number;MeanPowerW:number;Reported:Dist;Corrected:Dist}; type Cell={PowerLowerW:number;PowerUpperW:number;CadenceLowerRPM:number;CadenceUpperRPM:number;MeanLeft:number;MeanRight:number;Samples:number;DurationSeconds:number}; type Reg={InterceptLeftAtReference:number;PowerPPPer100W:number;CadencePPPer10RPM:number;RSquared:number;RMSE:number;Samples:number;ReferencePowerW:number;ReferenceCadenceRPM:number}; type Report={fileName:string;samples:number;durationSeconds:number;skipped:number;buckets:Bucket[];reportedHeatmap:Cell[];correctedHeatmap:Cell[];reportedRegression?:Reg;correctedRegression?:Reg};
 let dragging=false,file:File|null=null,input:HTMLInputElement; let left=160,right=165,configured=162.5,powerBucket=50,cadenceBucket=10,minSamples=5,minDuration=5; let loading=false,error='',report:Report|null=null,corrected=false;
 function choose(files:FileList|null){const next=files?.[0];if(next){if(!next.name.toLowerCase().endsWith('.fit')){error='Please choose a .FIT file.';return}file=next;error='';report=null}}
 async function analyse(){if(!file)return;loading=true;error='';const body=new FormData();body.set('file',file);for(const [k,v] of Object.entries({leftCrankMM:left,rightCrankMM:right,configuredCrankMM:configured,powerBucketW:powerBucket,cadenceBucketRPM:cadenceBucket,minSamples,minDurationSeconds:minDuration}))body.set(k,String(v));try{const res=await fetch('/api/analyse',{method:'POST',body});const data=await res.json();if(!res.ok)throw new Error(data.error||'Analysis failed');report=data;setTimeout(()=>document.querySelector('#results')?.scrollIntoView({behavior:'smooth'}),10)}catch(e){error=e instanceof Error?e.message:'Analysis failed'}finally{loading=false}}
 const f=(n:number,d=1)=>n.toFixed(d); const duration=(s:number)=>`${Math.floor(s/60)}m ${Math.round(s%60)}s`; const colour=(left:number)=>{const delta=Math.min(Math.abs(left-50)/5,1);return left>50?`rgba(202,255,66,${.12+delta*.58})`:`rgba(255,112,87,${.12+delta*.58})`};
</script>
<svelte:head><meta name="description" content="Explore cycling left/right power balance from a FIT file."/></svelte:head>
<header><a class="brand" href="/"><span>PB</span> Pedal Balance Lab</a><div class="privacy">Private ride analysis <i></i></div></header>
<main><section class="hero"><div class="eyebrow">CYCLING BIOMECHANICS · FIT ANALYSIS</div><h1>Find the signal in<br/>your pedal stroke.</h1><p>Drop in a ride. See how left/right balance changes with power and cadence, then correct for unequal crank lengths.</p></section>
<section class="workspace"><div class="step"><b>01</b><span>IMPORT RIDE</span></div><button class:dragging class="dropzone" onclick={()=>input.click()} ondragover={(e)=>{e.preventDefault();dragging=true}} ondragleave={()=>dragging=false} ondrop={(e)=>{e.preventDefault();dragging=false;choose(e.dataTransfer?.files??null)}}><input bind:this={input} type="file" accept=".fit" onchange={(e)=>choose(e.currentTarget.files)}/><span class="upload-icon">↥</span>{#if file}<strong>{file.name}</strong><small>{(file.size/1024/1024).toFixed(2)} MB · ready to analyse</small>{:else}<strong>Drop your .FIT file here</strong><small>or click to browse · max 25 MB</small>{/if}</button>
<div class="settings"><label>LEFT CRANK <span><input type="number" bind:value={left}/> mm</span></label><label>RIGHT CRANK <span><input type="number" bind:value={right}/> mm</span></label><label>CONFIGURED <span><input type="number" step=".5" bind:value={configured}/> mm</span></label><label>POWER BUCKET <span><input type="number" bind:value={powerBucket}/> W</span></label><label>CADENCE BUCKET <span><input type="number" bind:value={cadenceBucket}/> rpm</span></label><label>MIN SAMPLES <span><input type="number" bind:value={minSamples}/></span></label><label>MIN TIME <span><input type="number" bind:value={minDuration}/> sec</span></label></div><button class="analyse" disabled={!file||loading} onclick={analyse}>{loading?'ANALYSING…':'ANALYSE RIDE'} <span>→</span></button>{#if error}<p class="error" role="alert">{error}</p>{/if}</section>
{#if report}<section class="results" id="results"><div class="results-head"><div><span class="kicker">ANALYSIS COMPLETE</span><h2>{report.fileName}</h2></div><div class="metrics"><div><b>{report.samples.toLocaleString()}</b><span>valid samples</span></div><div><b>{duration(report.durationSeconds)}</b><span>represented</span></div><div><b>{report.skipped}</b><span>skipped</span></div></div></div>
<div class="section-title"><div><b>01</b><h3>Power buckets</h3></div><p>Reported and crank-length-corrected balance, shown as left/right.</p></div><div class="tablewrap"><table><thead><tr><th>POWER</th><th>SAMPLES</th><th>TIME</th><th>MEAN W</th><th>REPORTED L/R</th><th>CORRECTED L/R</th><th>MEDIAN</th><th>σ</th></tr></thead><tbody>{#each report.buckets as b}<tr><td>{b.LowerW}–{b.UpperW} W</td><td>{b.Samples}</td><td>{duration(b.DurationSeconds)}</td><td>{f(b.MeanPowerW,0)}</td><td class="balance">{f(b.Reported.MeanLeft)}/{f(100-b.Reported.MeanLeft)}</td><td class="balance corrected">{f(b.Corrected.MeanLeft)}/{f(100-b.Corrected.MeanLeft)}</td><td>{f(b.Reported.MedianLeft)}/{f(100-b.Reported.MedianLeft)}</td><td>{f(b.Reported.StdDev)}</td></tr>{/each}</tbody></table></div>
<div class="section-title"><div><b>02</b><h3>Power × cadence heatmap</h3></div><button class="toggle" onclick={()=>corrected=!corrected}><span class:active={!corrected}>REPORTED</span><span class:active={corrected}>CORRECTED</span></button></div><div class="heatmap"><div class="heat-note">Every tile shows LEFT / RIGHT · colour intensity shows departure from 50/50</div><div class="heat-grid">{#each (corrected?report.correctedHeatmap:report.reportedHeatmap) as cell}<div class="cell" style:background={colour(cell.MeanLeft)}><small>{cell.CadenceLowerRPM}–{cell.CadenceUpperRPM} rpm</small><strong>{f(cell.MeanLeft)}/{f(cell.MeanRight)}</strong><span>{cell.PowerLowerW}–{cell.PowerUpperW} W · n={cell.Samples}</span></div>{/each}</div></div>
<div class="section-title"><div><b>03</b><h3>Regression model</h3></div><p>L = a + bP + cC, centred at 200 W and 85 rpm.</p></div><div class="reg-grid">{#each [['Reported',report.reportedRegression],['Corrected',report.correctedRegression]] as pair}{#if pair[1]}{@const r=pair[1] as Reg}<article><span>{pair[0]}</span><strong>{f(r.InterceptLeftAtReference)} / {f(100-r.InterceptLeftAtReference)}</strong><p>Expected balance at {r.ReferencePowerW} W and {r.ReferenceCadenceRPM} rpm</p><dl><div><dt>POWER EFFECT</dt><dd>{r.PowerPPPer100W>=0?'+':''}{f(r.PowerPPPer100W,2)} pp / 100 W</dd></div><div><dt>CADENCE EFFECT</dt><dd>{r.CadencePPPer10RPM>=0?'+':''}{f(r.CadencePPPer10RPM,2)} pp / 10 rpm</dd></div><div><dt>R² / RMSE</dt><dd>{f(r.RSquared,3)} / {f(r.RMSE,2)} pp</dd></div></dl></article>{/if}{/each}</div></section>
{:else}<section class="preview"><div><span class="kicker">THE OUTPUT</span><h2>One ride.<br/>Three useful views.</h2></div><div class="cards"><article><b>01</b><h3>Power buckets</h3><p>Mean, median and variability at every intensity.</p></article><article><b>02</b><h3>Balance heatmap</h3><p>Actual L/R split across watts and cadence.</p></article><article><b>03</b><h3>Regression</h3><p>Separate the effects of power and cadence.</p></article></div></section>{/if}</main><footer>FIT files are discarded as soon as analysis completes. No account required.</footer>
